function Footer() {
    return (
        <footer className="text-center mt-8 mb-4 text-gray-600 dark:text-gray-400 text-sm"> {/* Added mb-4 */}
          {/* Using placeholder Link components */}
          <button onClick={() => handleNavLinkClick('privacy')} className="hover:underline mx-2 text-inherit">Privacy Policy</button> |
          <button onClick={() => handleNavLinkClick('terms')} className="hover:underline mx-2 text-inherit">Terms of Service</button>
          <p className="mt-1">&copy; {new Date().getFullYear()} Your Site Name. All rights reserved.</p>
      </footer>
    )
}

export default Footer;
